/// AC-001 / PC4: check_handoff_completeness returns Continue when the file
/// path does NOT end with HANDOFF.md. No YAML parsing occurs.
/// Red Gate: panics at todo!() in check_handoff_completeness.
#[test]
fn ac_001_non_handoff_path_noop() {
    let ctx = make_non_handoff_ctx("factory-artifacts/wave-state.yaml");
    let result = check_handoff_completeness(&ctx);
    assert_eq!(
        result,
        GateResult::Continue,
        "AC-001/PC4: non-HANDOFF.md path must return Continue (no-op)"
    );
}

/// AC-001 / PC4 GREEN-BY-DESIGN: path_is_handoff returns true iff the path
/// ends with HANDOFF.md (case-sensitive). This test PASSES against the stub.
#[test]
fn ac_001_path_is_handoff_green_by_design() {
    // Positive cases
    assert!(
        path_is_handoff("factory-artifacts/HANDOFF.md"),
        "factory-artifacts/HANDOFF.md must match"
    );
    assert!(path_is_handoff("HANDOFF.md"), "bare HANDOFF.md must match");
    assert!(
        path_is_handoff("/some/deep/path/HANDOFF.md"),
        "deep path must match"
    );
    // Negative cases — wrong suffix
    assert!(
        !path_is_handoff("factory-artifacts/STATE.md"),
        "STATE.md must NOT match"
    );
    assert!(
        !path_is_handoff("factory-artifacts/handoff.md"),
        "lowercase handoff.md must NOT match (case-sensitive)"
    );
    assert!(
        !path_is_handoff("HANDOFF.md.bak"),
        "HANDOFF.md.bak must NOT match"
    );
    assert!(!path_is_handoff(""), "empty string must NOT match");
}

