/// VP-083 / BC-4.14.001 PC8 — explicit fail-open test for on_post_tool_use.
///
/// In the native (non-WASM) unit harness, host::read_file always fails with
/// CapabilityDenied (-1). Therefore on_post_tool_use ALWAYS fail-opens to
/// HookResult::Continue BEFORE reaching the YAML-parsing logic. This test
/// explicitly names and verifies that property: the I/O shell returns Continue
/// on read failure (no-false-positive gate behavior per VP-083).
///
/// This is an EXPLICIT FAIL-OPEN test — it does NOT exercise the validation
/// outcome (complete/incomplete → Continue/Block). It verifies only that the
/// fail-open path itself produces Continue when host I/O is unavailable.
///
/// Validation-outcome assertions must use check_handoff_completeness (the pure
/// core) rather than on_post_tool_use in the native harness. See
/// test_wave_close_allowed_with_complete_handoff and test_wave_1_no_op above.
///
/// VP-083 §no-false-positive / BC-4.14.001 PC8 fail-open-on-read-error.
#[test]
fn test_on_post_tool_use_fails_open_on_read_error() {
    // Deliberately incomplete YAML — would produce Block via check_handoff_completeness.
    // However, on_post_tool_use in the native harness fail-opens before parsing
    // because host::read_file returns CapabilityDenied, so it returns Continue.
    let yaml = "wave_id: 2\n"; // missing all required fields
    let payload = make_write_payload("factory-artifacts/HANDOFF.md", yaml);
    let result = on_post_tool_use(payload);
    assert_eq!(
        result,
        HookResult::Continue,
        "VP-083/fail-open: on_post_tool_use must return Continue when host::read_file \
        fails (CapabilityDenied in non-WASM harness). Got: {result:?}"
    );
}

// ---------------------------------------------------------------------------
// Helper: construct a Write-tool HookPayload for a given HANDOFF.md path and content.
// ---------------------------------------------------------------------------

fn make_write_payload(file_path: &str, content: &str) -> vsdd_hook_sdk::HookPayload {
    let json = serde_json::json!({
        "event_name": "PostToolUse",
        "tool_name": "Write",
        "session_id": "integration-test-session",
        "dispatcher_trace_id": "integration-test-trace",
        "tool_input": {
            "file_path": file_path,
            "content": content
        },
        "tool_response": {
            "exit_code": 0
        }
    });
    serde_json::from_value(json).expect("HookPayload fixture must deserialize")
}

